document.addEventListener("DOMContentLoaded",()=>{var e=document.getElementById("loginForm");let s=document.getElementById("username"),n=document.getElementById("password"),d=document.getElementById("loginMessage");e.addEventListener("submit",e=>{e.preventDefault();var e=s.value,t=n.value;"user"===e&&"password"===t?(d.textContent="Login bem-sucedido!",d.classList.remove("error"),d.classList.add("success")):(d.textContent="Usuário ou senha inválidos.",d.classList.remove("success"),d.classList.add("error"))})});